<script setup lang="ts">
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import DataTable from './DataTable.vue'
defineProps<{run: Record<string, any>}>()
const route=useRoute(),router=useRouter()
const tabs=['hosts','ports','services','endpoints','credentials','screenshots','findings','events']
const metrics=['hosts','open_ports','services','endpoints','credentials','screenshots','findings','errors']
const tab=computed(()=>tabs.includes(String(route.query.tab))?String(route.query.tab):'hosts')
const fields:Record<string,string[]>={hosts:['ip','source','status','open_ports','services','first_seen_at','last_seen_at'],ports:['ip','port','transport','state','change'],services:['ip','port','transport','name','product','version','banner','confidence','details','change','first_seen_at','last_seen_at'],endpoints:['url','ip','port','source','status','details','screenshot'],credentials:['url','username','credential_id','status','evidence','attempted_at'],screenshots:['url','image','status','captured_at','error'],findings:['kind','severity','identity','evidence','created_at'],events:['created_at','stage','level','event_type','message','details']}
const filters:Record<string,string[]>={hosts:['new','unchanged','no-longer-observed'],ports:['open','no-longer-observed'],services:['open','new','changed','unchanged','no-longer-observed'],endpoints:['discovered','captured','error'],credentials:['not_attempted','not_supported','failed','successful','blocked','unknown'],screenshots:['pending','captured','error'],findings:['new_host','new_port','new_service','changed_service','credential_success','screenshot','scanner_error','no_longer_observed'],events:['info','warning','error']}
const columns=computed(()=>fields[tab.value].map(key=>({key,label:key.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase())})))
function filterHost(ip:string){void router.replace({query:{tab:'services',services_search:ip}})}
</script>
<template><div class="metrics"><div class="panel metric" v-for="key in metrics" :key="key"><span>{{key.replaceAll('_',' ')}}</span><strong>{{run.counts[key]||0}}</strong></div></div><nav class="tabs" aria-label="Network result sections"><button v-for="name in tabs" :key="name" :aria-current="tab===name?'page':undefined" :class="{active:tab===name}" @click="router.replace({query:{...route.query,tab:name}})">{{name[0].toUpperCase()+name.slice(1)}}</button></nav><DataTable :key="tab+'-'+String(route.query.services_search||'')" :query-key="tab" :endpoint="`/runs/${run.id}/${tab}`" :columns="columns" :status-options="filters[tab]" :refresh="['queued','running','pausing','stopping'].includes(run.status)?3000:0" filter-status><template #ip="{value}"><button class="text-button" @click="filterHost(value)">{{value}}</button></template><template #credential_id="{value}">Credential {{String(value).slice(0,8)}}… · masked</template><template #image="{row}"><a v-if="row.content_url" :href="row.content_url" target="_blank" rel="noopener"><img class="thumbnail" :src="row.thumbnail_url" :alt="`Screenshot of ${row.url}`" loading="lazy"></a><span v-else>Unavailable</span></template><template #screenshot="{row}"><button class="text-button" @click="router.replace({query:{tab:'screenshots',screenshots_search:row.url}})">View captures</button></template></DataTable></template>
